src='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Learn the repeating interior color cycle from the visible cells.
    chosen = None
    for period in range(2, 11):
        counts = [Counter() for _ in range(period)]
        for r in range(3, h):
            for c in range(3, w):
                value = grid[r][c]
                if value != 0:
                    counts[(r + c) % period][value] += 1
        mapping = [counter.most_common(1)[0][0] if counter else None for counter in counts]
        total = sum(sum(counter.values()) for counter in counts)
        score = sum(counter[mapping[i]] for i, counter in enumerate(counts) if mapping[i] is not None)
        if total and score / total >= 0.95:
            chosen = mapping
            break
    if chosen is None:
        period = 5
        counts = [Counter() for _ in range(period)]
        for r in range(3, h):
            for c in range(3, w):
                value = grid[r][c]
                if value != 0:
                    counts[(r + c) % period][value] += 1
        chosen = [counter.most_common(1)[0][0] if counter else 0 for counter in counts]
        period = len(chosen)
    else:
        period = len(chosen)

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                if r < 2 or c < 2:
                    out[r][c] = 1
                elif r == 2 or c == 2:
                    out[r][c] = 4
                else:
                    out[r][c] = chosen[(r + c) % period]
    return out
'''
